// src/services/participantService.ts
async function applyForEvent(params) {
  const { eventId, teamName, teamLeaderId, members } = params;
  const { data: event, error: evErr } = await supabase.from("events").select("*").eq("id", eventId).single();
  if (evErr || !event) {
    return { success: false, message: "Event not found." };
  }
  if (event.publication_status !== "published") {
    return { success: false, message: "Applications are only accepted for published events." };
  }
  if (event.registration_close_at && /* @__PURE__ */ new Date() > new Date(event.registration_close_at)) {
    return { success: false, message: "Registration for this event has closed." };
  }
  const totalMembers = 1 + members.length;
  if (totalMembers < event.minimum_team_size || totalMembers > event.maximum_team_size) {
    return {
      success: false,
      message: `Team size must be between ${event.minimum_team_size} and ${event.maximum_team_size} members (including the team leader).`
    };
  }
  const { data: existingApp } = await supabase.from("applications").select("id, team:teams!inner(*)").eq("event_id", eventId).eq("team.team_leader_id", teamLeaderId).maybeSingle();
  if (existingApp) {
    return { success: false, message: "You have already submitted an application for this event." };
  }
  const { data: team, error: teamErr } = await supabase.from("teams").insert({
    event_id: eventId,
    team_name: teamName.trim(),
    team_leader_id: teamLeaderId
  }).select().single();
  if (teamErr) {
    if (teamErr.code === "23505") {
      return { success: false, message: "A team with this name already exists in this hackathon." };
    }
    throw teamErr;
  }
  if (members.length > 0) {
    const memberRows = members.map((m) => ({
      team_id: team.id,
      name: m.name.trim(),
      email: m.email.trim().toLowerCase(),
      invitation_status: "pending"
    }));
    const { error: memErr } = await supabase.from("team_members").insert(memberRows);
    if (memErr) throw memErr;
  }
  const paymentStatus = event.registration_fee > 0 ? "pending" : "waived";
  const { data: application, error: appErr } = await supabase.from("applications").insert({
    event_id: eventId,
    team_id: team.id,
    application_status: "pending",
    payment_status: paymentStatus
  }).select("*, team:teams(*), event:events(*)").single();
  if (appErr) throw appErr;
  return {
    success: true,
    message: "Application submitted successfully!",
    application
  };
}
